const sizeClasses: Record<NonNullable<InputProps['size']>, string> = {
  sm: 'min-h-9 px-3 py-1.5 text-sm',
  md: 'min-h-10 px-3 py-2 text-sm',
  lg: 'min-h-12 px-4 py-2.5 text-base',
  auto: 'px-d-pad-x py-d-pad-y text-d-base min-h-d-row',
};

export function getWorkspaceRouteScope(pathname: string): WorkspaceRouteScope {
  const normalized = normalizePathname(pathname);
  const vehicleDisabled =
    VEHICLE_DISABLED_PATHS.has(normalized) ||
    VEHICLE_DISABLED_PREFIXES.some((prefix) =>
      isAtOrBelow(normalized, prefix),
    );

  return {
    range: RANGE_ENABLED_PATHS.has(normalized),
    vehicle: !vehicleDisabled,
  };
}

    query: query || t('explore.brief.noSearch', 'No search filter'),
    category: selectedSection === 'all' ? t('explore.all', 'All') : selectedSection,
  }),
},
{
  metricId: 'count', occurrenceId: 'vehicles', rawValue: vehicles?.length,
  label: t('explore.kpi.vehicles', 'Vehicles'),

export function useVehicles() {
  return useQuery({
    queryKey: vehicleKeys.all,
    queryFn: ({ signal }) => request<Vehicle[]>('/vehicles', { signal }),
    staleTime: STALE_TIMES.FAST,
    select: safeArray,
  });
}

export function safeArray<T>(value: T[] | T | null | undefined): T[] {
  if (Array.isArray(value)) return value;
  if (value == null) return [];
  console.warn('[safeArray] Expected array, got:', typeof value);
  return [];
}

// (so we pick up hidden pages too) and (b) catalog labels (so we match
// the user's mental model). De-dupe by path; honor the catalog's
// visibility gates so we never suggest a hidden page.
const visiblePaths = useMemo(() => new Set(catalog.map((c) => c.to)), [catalog]);
const suggestions = useMemo(() => {
  const fromRegistry = closestRoutes(query, ROUTE_REGISTRY, 5);
  const fromLabels = closestRoutes(
    query,
    catalog.map((c) => ({
      path: c.to,
      name: c.label.replace(/\s+/g, ''),
      label: c.label,
      i18nKey: c.labelKey,
    })),
    5,
  );
  const seen = new Set<string>();
  const merged: typeof fromRegistry = [];
  for (const r of [...fromRegistry, ...fromLabels]) {
    if (!visiblePaths.has(r.path)) continue;
    if (seen.has(r.path)) continue;
    seen.add(r.path);
    merged.push(r);
  }
  merged.sort((a, b) => a.distance - b.distance);

const q = normalize(query)
if (!q) return []

const scored: RouteSuggestion[] = []
for (const r of registry) {
  if (r.hidden) continue
  const pathDist = levenshtein(q, normalize(r.path))
  const labelDist = levenshtein(q, normalize(r.label))
  const distance = Math.min(pathDist, labelDist)
  if (distance <= 6) scored.push({ ...r, distance })
}
scored.sort((a, b) => a.distance - b.distance || a.path.localeCompare(b.path))

export function FadeIn({ children, delay = 0, className = '' }: FadeInProps) {
  const { reduce, durationMs } = useMotionPreference(400)
  // framer-motion never resolves a transition with a non-finite delay, which
  // would strand `children` at the initial `opacity: 0` (invisible). Coerce a
  // bad computed delay to 0, and skip it altogether under reduced motion.
  const safeDelay = reduce || !Number.isFinite(delay) ? 0 : Math.max(0, delay)
  return (
    <motion.div
      initial={reduce ? false : { opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: durationMs / 1000, delay: safeDelay, ease: 'easeOut' }}
